import{_ as a,o as e,c as r,a2 as d}from"./chunks/framework.Bum8orMG.js";const u=JSON.parse('{"title":"Inventory","description":"Every planned page, dashboard, application, block, layout and interaction in Katana UI.","frontmatter":{"title":"Inventory","description":"Every planned page, dashboard, application, block, layout and interaction in Katana UI."},"headers":[],"relativePath":"ui-kit/inventory.md","filePath":"ui-kit/inventory.md","lastUpdated":1790432985000}'),o={name:"ui-kit/inventory.md"};function n(i,t,s,l,c,h){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="inventory" tabindex="-1">Inventory <a class="header-anchor" href="#inventory" aria-label="Permalink to &quot;Inventory&quot;">​</a></h1><p>The full planned surface of Katana UI. Everything listed here is <strong>planned</strong>; see the <a href="./roadmap">roadmap</a> for delivery order.</p><h2 id="dashboards-8" tabindex="-1">Dashboards (8) <a class="header-anchor" href="#dashboards-8" aria-label="Permalink to &quot;Dashboards (8)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Dashboard</th><th>Focus</th></tr></thead><tbody><tr><td>CRM</td><td>Contacts, deals pipeline, activity tracking, revenue forecasting.</td></tr><tr><td>E-commerce</td><td>Sales, products, orders, customers and conversion funnels.</td></tr><tr><td>Gen-AI</td><td>Token usage, prompt activity, model costs and generation quality.</td></tr><tr><td>Growth</td><td>Acquisition, activation, retention and experiment tracking.</td></tr><tr><td>AI Ops</td><td>Model health, latency, failure rates and evaluation runs.</td></tr><tr><td>Corporate Finance</td><td>P&amp;L, cash flow, budgets and variance analysis.</td></tr><tr><td>Site Reliability Engineering</td><td>SLIs, SLOs, error budgets, incidents and on-call.</td></tr><tr><td>Security Operations</td><td>Alerts, threat feeds, audit trail and access anomalies.</td></tr></tbody></table><h2 id="marketing" tabindex="-1">Marketing <a class="header-anchor" href="#marketing" aria-label="Permalink to &quot;Marketing&quot;">​</a></h2><ul><li>Landing page — hero, feature grid, social proof, pricing, FAQ and footer.</li></ul><h2 id="e-commerce-10" tabindex="-1">E-commerce (10) <a class="header-anchor" href="#e-commerce-10" aria-label="Permalink to &quot;E-commerce (10)&quot;">​</a></h2><p>Product catalog · Product detail · Cart · Checkout · Order confirmation · Orders · Order detail · Customers · Inventory · Promotions. Every page includes tables, forms or cards as appropriate, with empty, loading and error states.</p><h2 id="applications" tabindex="-1">Applications <a class="header-anchor" href="#applications" aria-label="Permalink to &quot;Applications&quot;">​</a></h2><table tabindex="0"><thead><tr><th>App</th><th>Pages</th></tr></thead><tbody><tr><td>File manager</td><td>Tree navigation, grid/list views, upload dropzone, preview drawer.</td></tr><tr><td>Chat</td><td>Conversation list, message thread, composer, presence, attachments.</td></tr><tr><td>Gen-AI</td><td>Home, Images, Content creator, Library.</td></tr><tr><td>Agentic Storage</td><td>Agent memory browser: artifacts, sessions, embeddings and retention controls.</td></tr></tbody></table><h2 id="authentication-4" tabindex="-1">Authentication (4) <a class="header-anchor" href="#authentication-4" aria-label="Permalink to &quot;Authentication (4)&quot;">​</a></h2><p>Sign in · Sign up · Forgot password · Reset password. Includes validation states, error handling and success screens.</p><h2 id="account-and-support" tabindex="-1">Account and support <a class="header-anchor" href="#account-and-support" aria-label="Permalink to &quot;Account and support&quot;">​</a></h2><ul><li>Profile settings — personal data, security, notifications, connected accounts.</li><li>Support/FAQ — searchable questions, categories, contact form.</li></ul><h2 id="foundations" tabindex="-1">Foundations <a class="header-anchor" href="#foundations" aria-label="Permalink to &quot;Foundations&quot;">​</a></h2><ul><li>Foundation component example — a documented reference component that demonstrates the full pipeline: tokens, primitive, binding, docs, tests, a11y map and LLM metadata.</li></ul><h2 id="ui-blocks-16-planned-15-required" tabindex="-1">UI blocks (16 planned, 15+ required) <a class="header-anchor" href="#ui-blocks-16-planned-15-required" aria-label="Permalink to &quot;UI blocks (16 planned, 15+ required)&quot;">​</a></h2><p>Page header · KPI stats row · Chart card · Data table with toolbar · Filter bar · Empty state · Activity feed · Timeline · Notification list · Team members · Pricing cards · File list · Chat thread · Wizard steps · Form section · CTA banner.</p><h2 id="common-layouts-50" tabindex="-1">Common layouts (50+) <a class="header-anchor" href="#common-layouts-50" aria-label="Permalink to &quot;Common layouts (50+)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Family</th><th>Count</th></tr></thead><tbody><tr><td>Dashboard shells</td><td>8</td></tr><tr><td>Auth shells</td><td>4</td></tr><tr><td>List/table layouts</td><td>6</td></tr><tr><td>Record/detail layouts</td><td>6</td></tr><tr><td>Settings layouts</td><td>6</td></tr><tr><td>Form layouts</td><td>6</td></tr><tr><td>Marketing sections</td><td>6</td></tr><tr><td>App layouts (file manager, chat, Gen-AI, storage)</td><td>4</td></tr><tr><td>Utility layouts (404, 500, maintenance, onboarding)</td><td>4</td></tr><tr><td><strong>Total</strong></td><td><strong>50</strong></td></tr></tbody></table><h2 id="interaction-examples-100" tabindex="-1">Interaction examples (100+) <a class="header-anchor" href="#interaction-examples-100" aria-label="Permalink to &quot;Interaction examples (100+)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Family</th><th>Count</th><th>Examples</th></tr></thead><tbody><tr><td>Overlays</td><td>20</td><td>Dropdown, select, combobox, popover, tooltip, modal, drawer, sheet, toast, context menu, command palette, date picker, color picker, tour, lightbox.</td></tr><tr><td>Navigation</td><td>15</td><td>Tabs, breadcrumbs, pagination, sidebar collapse, stepper, segmented control, tree view, skip links.</td></tr><tr><td>Forms</td><td>25</td><td>Validation, masked input, autocomplete, file dropzone, rich text, inline edit, multi-step form, OTP input.</td></tr><tr><td>Data</td><td>20</td><td>Sortable and filterable tables, virtualized lists, bulk actions, drag and drop, column pinning, export.</td></tr><tr><td>Charts</td><td>10</td><td>Interactive line, bar, donut, heatmap, radar and candlestick examples with ApexCharts.</td></tr><tr><td>Editors and media</td><td>10</td><td>Code editor, markdown editor, image cropper, video player, audio recorder, PDF preview.</td></tr></tbody></table><p>Plugin integrations are documented per example: charts (ApexCharts), editors, calendar, maps, drag and drop, and clipboard.</p><h2 id="charts" tabindex="-1">Charts <a class="header-anchor" href="#charts" aria-label="Permalink to &quot;Charts&quot;">​</a></h2><p>ApexCharts is the default adapter for: line, area, bar, column, pie, donut, radial bar, radar, polar area, heatmap, treemap, candlestick, bubble, scatter and range charts. Every chart is wrapped by a block that speaks the Safe Result contract for its data source.</p><h2 id="themes" tabindex="-1">Themes <a class="header-anchor" href="#themes" aria-label="Permalink to &quot;Themes&quot;">​</a></h2><p>Six curated themes plus the token contract for custom themes. Any theme that defines the <code>--kt-*</code> variables works, and an optional daisyUI preset maps the tokens to daisyUI themes.</p><h2 id="llm-files" tabindex="-1">LLM files <a class="header-anchor" href="#llm-files" aria-label="Permalink to &quot;LLM files&quot;">​</a></h2><p>Machine-readable artifacts generated from component metadata: <code>llms.txt</code>, <code>llms-full.txt</code>, a component registry and per-block markdown. See <a href="./llm-files">LLM files</a>.</p>',29)])])}const m=a(o,[["render",n]]);export{u as __pageData,m as default};
